static int dist(int *p) {
  return p[0] * p[0] + p[1] * p[1];
}

static int cmp(const void *a, const void *b) {
  return dist(*(int **)a) - dist(*(int **)b);
}

int **kClosest(int **points, int pointsSize, int *pointsColSize, int K, int *returnSize, int **returnColumnSizes) {
  qsort(points, pointsSize, sizeof(int *), cmp);
  int **res = (int **)malloc(sizeof(int *) * K);
  *returnColumnSizes = (int *)malloc(sizeof(int) * K);
  *returnSize = K;
  for (int i = 0; i < K; i++) {
    res[i] = (int *)malloc(sizeof(int) * 2);
    res[i][0] = points[i][0];
    res[i][1] = points[i][1];
    (*returnColumnSizes)[i] = 2;
  }
  return res;
}

class Solution {
public:
  vector<vector<int>> kClosest(vector<vector<int>> &points, int K) {
    nth_element(points.begin(), points.begin() + K, points.end(),
                [](vector<int> &p, vector<int> &q) {
                  return p[0] * p[0] + p[1] * p[1] < q[0] * q[0] + q[1] * q[1];
                });
    return vector<vector<int>>(points.begin(), points.begin() + K);
  }

  static bool f(vector<int> p1, vector<int> p2) {
    return p1[0] * p1[0] + p1[1] * p1[1] < p2[0] * p2[0] + p2[1] * p2[1];
  }
};

func kClosest(points [][]int, K int) [][]int {
	sort.Slice(points, func(i, j int) bool {
		return points[i][0]*points[i][0]+points[i][1]*points[i][1] < points[j][0]*points[j][0]+points[j][1]*points[j][1]
	})
	return points[:K]
}

class Solution {
  public int[][] kClosest(int[][] points, int K) {
    Arrays.sort(points, (a, b) -> (a[0] * a[0] + a[1] * a[1]) - (b[0] * b[0] + b[1] * b[1]));
    return Arrays.copyOfRange(points, 0, K);
  }
}

class Solution:
    def kClosest(self, points: List[List[int]], K: int) -> List[List[int]]:
        points.sort(key=lambda p: p[0] * p[0] + p[1] * p[1])
        return points[:K]

impl Solution {
  pub fn k_closest(points: Vec<Vec<i32>>, k: i32) -> Vec<Vec<i32>> {
    let mut points = points;
    points.sort_by_key(|p| p[0] * p[0] + p[1] * p[1]);
    points[..k as usize].to_vec()
  }
}

const kClosest = (points: number[][], K: number): number[][] => {
  points.sort((a, b) => a[0] * a[0] + a[1] * a[1] - (b[0] * b[0] + b[1] * b[1]));
  return points.slice(0, K);
};
